$ErrorActionPreference='Stop'
$base='http://127.0.0.1:8770/interviews';$origin='http://127.0.0.1:8770';$script:checks=0
function Check([bool]$condition,[string]$message){if(-not $condition){throw "Resume HTTP failed: $message"};$script:checks++}
function Token([string]$html){$match=[regex]::Match($html,'name="_token" value="([^"]+)"');if(-not $match.Success){throw 'CSRF token missing'};return $match.Groups[1].Value}
function Status([scriptblock]$request){try{&$request|Out-Null;return 200}catch{return [int]$_.Exception.Response.StatusCode}}
function Login([string]$identity,[string]$password){$s=New-Object Microsoft.PowerShell.Commands.WebRequestSession;$f=Invoke-WebRequest "$base/login" -WebSession $s -UseBasicParsing;$p=Invoke-WebRequest "$base/login" -WebSession $s -Method Post -Body @{_token=Token $f.Content;identity=$identity;password=$password} -UseBasicParsing;return @{Session=$s;Page=$p}}
function Add-ZipText($zip,[string]$name,[string]$value){$entry=$zip.CreateEntry($name);$stream=$entry.Open();$writer=New-Object IO.StreamWriter($stream,[Text.UTF8Encoding]::new($false));$writer.Write($value);$writer.Dispose();$stream.Dispose()}
function Register-Candidate([string]$name,[string]$phone,[string]$file,[string]$filename,[string]$mime,[string]$jar,[string]$output){$form=& curl.exe -sS -c $jar "$base/register";$token=Token $form;$technology=[regex]::Match($form,'name="technology_ids\[\]" value="(\d+)"').Groups[1].Value;$args=@('-sS','-L','-b',$jar,'-c',$jar,'-F',"_token=$token",'-F',"full_name=$name",'-F',"phone=$phone",'-F','password=ResumeTesting12!','-F',"technology_ids[]=$technology",'-F','classification=Genuine');if($file){$args+=@('-F',"resume=@$file;filename=$filename;type=$mime")};$args+=@("$base/register",'-o',$output);& curl.exe @args}

$temp=Join-Path $env:TEMP ('blujay-resume-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp|Out-Null
$pdf=Join-Path $temp 'valid.pdf';[IO.File]::WriteAllText($pdf,"%PDF-1.4`n1 0 obj`n<<>>`nendobj`ntrailer`n<<>>`n%%EOF`n",[Text.Encoding]::ASCII)
$replacement=Join-Path $temp 'replacement.pdf';[IO.File]::WriteAllText($replacement,"%PDF-1.4`n1 0 obj`n<</Title(Replacement)>>`nendobj`ntrailer`n<<>>`n%%EOF`n",[Text.Encoding]::ASCII)
$docx=Join-Path $temp 'valid.docx';Add-Type -AssemblyName System.IO.Compression;Add-Type -AssemblyName System.IO.Compression.FileSystem;$zip=[IO.Compression.ZipFile]::Open($docx,[IO.Compression.ZipArchiveMode]::Create);Add-ZipText $zip '[Content_Types].xml' '<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>';Add-ZipText $zip '_rels/.rels' '<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"></Relationships>';Add-ZipText $zip 'word/document.xml' '<?xml version="1.0"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body/></w:document>';$zip.Dispose()
$phpFile=Join-Path $temp 'shell.pdf';[IO.File]::WriteAllText($phpFile,'<?php echo "owned";')
$fakeDocx=Join-Path $temp 'fake.docx';[IO.File]::WriteAllText($fakeDocx,'PK fake office file')
$oversized=Join-Path $temp 'large.pdf';$large=[IO.File]::OpenWrite($oversized);$large.SetLength(5MB+1);$large.Dispose()

$pdfJar=Join-Path $temp 'pdf-cookie.txt';$pdfPage=Join-Path $temp 'pdf-page.html';Register-Candidate 'PDF Resume Candidate' '+919733333301' $pdf 'Chaitanya_Resume.pdf' 'application/pdf' $pdfJar $pdfPage;$pdfHtml=Get-Content $pdfPage -Raw;Check ($pdfHtml.Contains('Your interview workspace')) 'registration with valid PDF succeeds'
$docxJar=Join-Path $temp 'docx-cookie.txt';$docxPage=Join-Path $temp 'docx-page.html';Register-Candidate 'DOCX Resume Candidate' '+919733333302' $docx 'Candidate_Profile.docx' 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' $docxJar $docxPage;$docxHtml=Get-Content $docxPage -Raw;Check ($docxHtml.Contains('Your interview workspace')) 'registration with valid DOCX succeeds'
foreach($attack in @(@('PHP Attack','+919733333303',$phpFile,'shell.pdf','application/pdf','not a valid PDF'),@('Fake DOCX','+919733333304',$fakeDocx,'fake.docx','application/vnd.openxmlformats-officedocument.wordprocessingml.document','not a valid DOCX'),@('Double Extension','+919733333305',$pdf,'resume.php.pdf','application/pdf','single .pdf'),@('Oversized Resume','+919733333306',$oversized,'large.pdf','application/pdf','up to 5 MB'))){$jar=Join-Path $temp (([guid]::NewGuid().ToString('N'))+'.txt');$out=Join-Path $temp (([guid]::NewGuid().ToString('N'))+'.html');Register-Candidate $attack[0] $attack[1] $attack[2] $attack[3] $attack[4] $jar $out;$body=Get-Content $out -Raw;Check ($body.Contains($attack[5])) ("upload rejected: "+$attack[0])}

$ownPdfHeaders=Join-Path $temp 'own-pdf-headers.txt';$ownPdfCode=& curl.exe -sS -D $ownPdfHeaders -o (Join-Path $temp 'own.pdf') -w '%{http_code}' -b $pdfJar "$base/profile/resume";Check ($ownPdfCode -eq '200' -and (Get-Content $ownPdfHeaders -Raw).Contains('Content-Type: application/pdf') -and (Get-Content $ownPdfHeaders -Raw).Contains('inline;')) 'candidate views own PDF resume inline'
$ownDocxHeaders=Join-Path $temp 'own-docx-headers.txt';$ownDocxCode=& curl.exe -sS -D $ownDocxHeaders -o (Join-Path $temp 'own.docx') -w '%{http_code}' -b $docxJar "$base/profile/resume";Check ($ownDocxCode -eq '200' -and (Get-Content $ownDocxHeaders -Raw).Contains('attachment;')) 'candidate downloads own DOCX resume'

$adminLogin=Login 'resume.admin' 'ResumeAdmin12!';$admin=$adminLogin.Session;Check $adminLogin.Page.Content.Contains('Operations dashboard') 'admin login succeeds'
$pdfDirectory=Invoke-WebRequest "$base/admin/candidates?search=PDF%20Resume%20Candidate" -WebSession $admin -UseBasicParsing;$pdfId=[regex]::Match($pdfDirectory.Content,'admin/candidate\?id=(\d+)').Groups[1].Value;Check ($pdfId -and $pdfDirectory.Content.Contains('Resume')) 'admin directory displays resume indicator'
$docxDirectory=Invoke-WebRequest "$base/admin/candidates?search=DOCX%20Resume%20Candidate" -WebSession $admin -UseBasicParsing;$docxId=[regex]::Match($docxDirectory.Content,'admin/candidate\?id=(\d+)').Groups[1].Value
$pdfDetail=Invoke-WebRequest "$base/admin/candidate?id=$pdfId" -WebSession $admin -UseBasicParsing;Check ($pdfDetail.Content.Contains('Chaitanya_Resume.pdf') -and $pdfDetail.Content.Contains('View Resume') -and $pdfDetail.Content.Contains('Download Resume')) 'admin candidate detail displays resume metadata and actions'
$adminView=Invoke-WebRequest "$base/profile/resume?id=$pdfId" -WebSession $admin -UseBasicParsing;Check ($adminView.StatusCode -eq 200 -and $adminView.Headers['Content-Disposition'].Contains('inline')) 'admin views candidate PDF without impersonation'
$adminDownload=Invoke-WebRequest "$base/profile/resume?id=$docxId&download=1" -WebSession $admin -UseBasicParsing;Check ($adminDownload.StatusCode -eq 200 -and $adminDownload.Headers['Content-Disposition'].Contains('attachment')) 'admin downloads candidate DOCX'
$idorCode=& curl.exe -sS -o NUL -w '%{http_code}' -b $pdfJar "$base/profile/resume?id=$docxId";Check ($idorCode -eq '404') 'Candidate A cannot access Candidate B resume'
$guestCode=& curl.exe -sS -o NUL -w '%{http_code}' "$base/profile/resume?id=$pdfId";Check ($guestCode -eq '303') 'unauthenticated resume access is rejected'

$beforeReplace=@(Get-ChildItem (Join-Path (Get-Location) 'storage/resumes') -File|Select-Object -ExpandProperty Name);$profile=& curl.exe -sS -b $pdfJar -c $pdfJar "$base/profile";$profileToken=Token $profile;$replacePage=Join-Path $temp 'replace.html';& curl.exe -sS -L -b $pdfJar -c $pdfJar -F "_token=$profileToken" -F "resume=@$replacement;filename=Updated_Resume.pdf;type=application/pdf" "$base/profile/resume" -o $replacePage;$afterReplace=@(Get-ChildItem (Join-Path (Get-Location) 'storage/resumes') -File|Select-Object -ExpandProperty Name);$removed=@($beforeReplace|Where-Object{$_ -notin $afterReplace});$added=@($afterReplace|Where-Object{$_ -notin $beforeReplace});Check ((Get-Content $replacePage -Raw).Contains('Your resume was uploaded securely') -and $removed.Count -eq 1 -and $added.Count -eq 1) 'candidate replaces resume and old private file is cleaned up'

$pdfDetail=Invoke-WebRequest "$base/admin/candidate?id=$pdfId" -WebSession $admin -UseBasicParsing;$deactivated=Invoke-WebRequest "$base/admin/candidate/deactivate" -WebSession $admin -Method Post -Body @{_token=Token $pdfDetail.Content;candidate_id=$pdfId} -UseBasicParsing;Check $deactivated.Content.Contains('Candidate deactivated') 'candidate with resume can be deactivated';$inactiveResume=Invoke-WebRequest "$base/profile/resume?id=$pdfId" -WebSession $admin -UseBasicParsing;Check ($inactiveResume.StatusCode -eq 200) 'deactivation preserves resume and admin access'
$docxDetail=Invoke-WebRequest "$base/admin/candidate?id=$docxId" -WebSession $admin -UseBasicParsing;$filesBeforeDelete=@(Get-ChildItem (Join-Path (Get-Location) 'storage/resumes') -File|Select-Object -ExpandProperty Name);$deleted=Invoke-WebRequest "$base/admin/candidate/delete" -WebSession $admin -Method Post -Body @{_token=Token $docxDetail.Content;candidate_id=$docxId;confirmation_name='DELETE'} -UseBasicParsing;$filesAfterDelete=@(Get-ChildItem (Join-Path (Get-Location) 'storage/resumes') -File|Select-Object -ExpandProperty Name);Check ($deleted.Content.Contains('Candidate permanently deleted') -and $filesAfterDelete.Count -eq $filesBeforeDelete.Count-1) 'permanent candidate deletion removes resume metadata and private file'

Remove-Item -LiteralPath $temp -Recurse -Force
Write-Output "$checks Resume HTTP/security checks passed."
